"use client"

import * as React from "react"
import * as ResizablePrimitive from "react-resizable-panels"
import "./minecraft-resizable.css"
import "./minecraft-resizable-assets.css"

const ScaleContext=React.createContext<1|2|3>(2)

function ResizablePanelGroup({className,scale=2,style,...props}:ResizablePrimitive.GroupProps & {scale?:1|2|3}){
 return <ScaleContext.Provider value={scale}><ResizablePrimitive.Group data-slot="resizable-panel-group" className={`mc-resizable-group ${className??""}`} style={{"--mc-scale":scale,...style} as React.CSSProperties} {...props}/></ScaleContext.Provider>
}

function ResizablePanel({className,...props}:ResizablePrimitive.PanelProps){return <ResizablePrimitive.Panel data-slot="resizable-panel" className={`mc-resizable-panel ${className??""}`} {...props}/>}

function ResizableHandle({withHandle=false,className,style,children,scale:scaleProp,...props}:ResizablePrimitive.SeparatorProps & {withHandle?:boolean;scale?:1|2|3}){
 const inherited=React.useContext(ScaleContext),scale=scaleProp??inherited
 return <ResizablePrimitive.Separator data-slot="resizable-handle" data-with-handle={String(withHandle)} className={`mc-resizable-handle ${className??""}`} style={{"--mc-scale":scale,...style} as React.CSSProperties} {...props}>
  {children}<span className="mc-resizable-track" aria-hidden="true"/>{withHandle?<span data-slot="resizable-grip" className="mc-resizable-grip" aria-hidden="true"><span data-slot="resizable-arrow" data-direction="backward" className="mc-resizable-arrow"/><span data-slot="resizable-arrow" data-direction="forward" className="mc-resizable-arrow"/></span>:null}
 </ResizablePrimitive.Separator>
}

export {ResizablePanelGroup,ResizablePanel,ResizableHandle}

@layer components {
 .mc-resizable-group { width:100%; height:100%; }
 .mc-resizable-panel { min-width:0; min-height:0; }
 .mc-resizable-handle { --mc-pixel:calc(1px * var(--mc-scale,2)); position:relative; flex-shrink:0; outline:none; image-rendering:pixelated; touch-action:none; }
 .mc-resizable-handle[aria-orientation="vertical"] { width:calc(6 * var(--mc-pixel)); align-self:stretch; cursor:col-resize; }
 .mc-resizable-handle[aria-orientation="horizontal"] { height:calc(6 * var(--mc-pixel)); align-self:stretch; cursor:row-resize; }
 .mc-resizable-handle[data-with-handle="true"][aria-orientation="vertical"] { width:calc(28 * var(--mc-pixel)); }
 .mc-resizable-handle[data-with-handle="true"][aria-orientation="horizontal"] { height:calc(28 * var(--mc-pixel)); }
 .mc-resizable-track { position:absolute; top:0; bottom:0; left:50%; width:calc(2 * var(--mc-pixel)); transform:translateX(-50%); background:#111; box-shadow:var(--mc-pixel) 0 #555; pointer-events:none; }
 .mc-resizable-handle[aria-orientation="horizontal"] > .mc-resizable-track { top:50%; bottom:auto; left:0; right:0; width:auto; height:calc(2 * var(--mc-pixel)); transform:translateY(-50%); box-shadow:0 var(--mc-pixel) #555; }
 .mc-resizable-handle[data-with-handle="true"] > .mc-resizable-track { mask-image:linear-gradient(to bottom,#000 calc(50% - 10 * var(--mc-pixel)),transparent calc(50% - 10 * var(--mc-pixel)),transparent calc(50% + 10 * var(--mc-pixel)),#000 calc(50% + 10 * var(--mc-pixel))); }
 .mc-resizable-handle[data-with-handle="true"][aria-orientation="horizontal"] > .mc-resizable-track { mask-image:linear-gradient(to right,#000 calc(50% - 10 * var(--mc-pixel)),transparent calc(50% - 10 * var(--mc-pixel)),transparent calc(50% + 10 * var(--mc-pixel)),#000 calc(50% + 10 * var(--mc-pixel))); }
 .mc-resizable-grip { display:flex; gap:calc(2 * var(--mc-pixel)); position:absolute; width:calc(26 * var(--mc-pixel)); height:calc(17 * var(--mc-pixel)); top:calc(round(down,50%,var(--mc-pixel)) - 8 * var(--mc-pixel)); left:calc(round(down,50%,var(--mc-pixel)) - 13 * var(--mc-pixel)); pointer-events:none; }
 .mc-resizable-grip > .mc-resizable-arrow { display:block; flex:none; width:calc(12 * var(--mc-pixel)); height:calc(17 * var(--mc-pixel)); background:var(--mc-pagination-arrow) center/100% 100% no-repeat; image-rendering:pixelated; }
 .mc-resizable-handle[aria-orientation="horizontal"] > .mc-resizable-grip { left:calc(round(down,50%,var(--mc-pixel)) + 9 * var(--mc-pixel)); top:calc(round(down,50%,var(--mc-pixel)) - 13 * var(--mc-pixel)); transform:rotate(90deg); transform-origin:0 0; }
 .mc-resizable-handle:hover .mc-resizable-arrow,.mc-resizable-handle:focus-visible .mc-resizable-arrow { background-image:var(--mc-pagination-arrow-highlighted); }
 .mc-resizable-handle:focus-visible > .mc-resizable-grip { outline:var(--mc-pixel) solid #fff; outline-offset:var(--mc-pixel); }
 .mc-resizable-handle[data-with-handle="false"]:focus-visible { outline:var(--mc-pixel) solid #fff; outline-offset:calc(-1 * var(--mc-pixel)); }
 .mc-resizable-handle[aria-disabled="true"] { cursor:default; }
}
